function friendlyErrorMessage(error,fallback='操作失败'){const runtime=window.YanceRuntimeErrors,code=String(runtime?.reasonCode?.(error)||error?.reasonCode||error?.code||'').toUpperCase(),raw=String(error?.userMessage||error?.message||(typeof error==='string'?error:'')||'').trim();if(code==='MEDIA_FRAME_CONVERTER_NOT_CONFIGURED')return'动态贴纸、GIF 或视频识别需要 FFmpeg，请先完成本地语音组件安装。';if(code==='MEDIA_FRAME_EXTRACTION_FAILED'||code==='MEDIA_FRAME_EMPTY')return'未能从动态贴纸、GIF 或视频中提取可识别画面。';if(code==='MEDIA_NOT_CACHED')return'媒体尚未恢复到本机，请先重试恢复媒体。';if(/FAILED TO LOAD IMAGE OR AUDIO FILE|INVALID_REQUEST_ERROR/i.test(raw))return'模型未能读取此媒体。系统已停止提交原始动态文件，请恢复媒体或提取代表画面后重试。';if(/MMG\.WHATSAPP\.NET|FAILED TO FETCH STREAM/i.test(raw))return'WhatsApp 原下载凭证已经失效，请从消息卡片重新同步媒体。';if(/^\s*[\[{]/.test(raw)){try{const parsed=JSON.parse(raw);return friendlyErrorMessage(parsed?.error||parsed?.message||parsed,fallback)}catch(_){}}if(runtime?.userMessage)return runtime.userMessage(error,{rootObject:window,fallback});return raw&&raw!=='[object Object]'?raw.slice(0,260):fallback}
