function capabilityDecision(name,options={}){const c=contact()||{},runtime=window.YancePlatformCapabilityRuntime;if(runtime?.actionDecision)return runtime.actionDecision(c,name,{fallback:options.fallback??false,routeContext:routeContext(),evaluateRoute:options.evaluateRoute??true,...options});const value=c?.capabilities?.[name],supported=value===true||value==='partial'||value==='policy'||value==='permission';return {name,state:supported?(value===true?'supported':String(value)):'unsupported',supported,fullySupported:value===true,visible:supported||options.showUnavailable===true,enabled:supported,reason:supported?'':'当前平台不支持此操作',stateLabel:supported?'平台支持':'当前平台不支持'}}
