function newIdempotencyKey(prefix='send'){return globalThis.crypto?.randomUUID?.()||`${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function uncertainSendFailure(error){const code=String(error?.code||error?.reasonCode||'').toUpperCase();return error?.name==='TimeoutError'||error?.name==='AbortError'||/NETWORK|INVALID_RESPONSE|ABORT_ERR|REQUEST_TIMEOUT/.test(code)}
function sendFailure(payload,response,label){if(window.YanceRuntimeErrors?.createError)return window.YanceRuntimeErrors.createError(payload,{status:response.status,rootObject:window,fallback:`${label}失败（HTTP ${response.status}）`});const error=new Error(friendlyErrorMessage(payload,`${label}失败（HTTP ${response.status}）`));error.code=payload?.code||payload?.reasonCode||payload?.error?.reasonCode||'SEND_REQUEST_FAILED';error.status=response.status;error.payload=payload;return error}
async function parseJsonResponse(response,label='请求'){let payload;try{payload=await response.json()}catch(cause){const error=new Error(`${label}返回了无法解析的响应`);error.code='R32_INVALID_RESPONSE';error.status=response.status;error.cause=cause;throw error}if(!payload||typeof payload!=='object'){const error=new Error(`${label}返回了无效响应`);error.code='R32_INVALID_RESPONSE';error.status=response.status;throw error}if(!response.ok||payload.ok===false)throw sendFailure(payload,response,label);return payload}
async function fetchJsonWithTimeout(url,options={},config={}){const timeoutMs=Math.max(1000,Number(config.timeoutMs||60000)),controller=new AbortController();let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort()},timeoutMs);try{return await parseJsonResponse(await fetch(url,{...options,signal:controller.signal}),config.label||'请求')}catch(error){if(timedOut){const timeout=new DOMException(`${config.label||'请求'}超时`,'TimeoutError');timeout.code='SEND_RESPONSE_TIMEOUT';throw timeout}if(error?.name==='TypeError'){error.code=error.code||'SEND_NETWORK_UNAVAILABLE'}throw error}finally{clearTimeout(timer)}}
