function queueStateLabel(state=''){return ({queued:'已进入发送队列',pending:'等待发送',sending:'正在发送',retry:'网络异常，等待自动重试',failed:'发送失败',sent:'发送成功',cancelled:'已取消',platform_accepted_local_pending:'平台已发送，正在修复本地记录',send_outcome_unknown:'发送结果不确定，已禁止自动重发'})[String(state).toLowerCase()]||'发送状态更新'}
async function loadPersistedSendQueueState(options={}){const c=contact(),conversationId=String(c?.id||'');if(!conversationId){sendQueueState=null;sendQueueLoadConversationId='';sendQueueLoadedAt=0;renderSendQueueStatus();return null}const force=options?.force===true,now=Date.now();if(!force&&sendQueueLoadPromise&&sendQueueLoadConversationId===conversationId)return sendQueueLoadPromise;if(!force&&sendQueueLoadConversationId===conversationId&&now-sendQueueLoadedAt<1500)return sendQueueState;const requestKey=`${conversationId}:${now}`;sendQueueLoadKey=requestKey;sendQueueLoadConversationId=conversationId;const task=(async()=>{try{const result=await window.YanceCore?.messages?.listQueue?.({limit:500}),rows=Array.isArray(result?.queue)?result.queue:[];if(sendQueueLoadKey!==requestKey||String(contact()?.id||'')!==conversationId)return null;const priority={send_outcome_unknown:0,platform_accepted_local_pending:1,sending:2,retry:3,pending:4,queued:5,failed:6},active=rows.filter(row=>String(row.sessionKey||'')===conversationId&&!['sent','cancelled'].includes(String(row.state||'').toLowerCase())).sort((a,b)=>(priority[String(a.state||'').toLowerCase()]??9)-(priority[String(b.state||'').toLowerCase()]??9)||String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0]||null;sendQueueState=active;sendQueueLoadedAt=Date.now();renderSendQueueStatus();return active}catch(error){console.warn('[R32 send queue restore]',error);return null}})();sendQueueLoadPromise=task;try{return await task}finally{if(sendQueueLoadPromise===task)sendQueueLoadPromise=null}}
function schedulePersistedSendQueueState(options={}){clearTimeout(sendQueueRefreshTimer);const delay=Math.max(0,Number(options.delayMs??80));sendQueueRefreshTimer=setTimeout(()=>{sendQueueRefreshTimer=0;loadPersistedSendQueueState({force:options.force===true})},delay)}
async function reconcileQueueOutcome(queueId,resolution){const confirmedSent=resolution==='confirmed_sent',prompt=confirmedSent?'请先在对应平台核对。确认这条消息已经发送成功，并将本地记录标记为已发送吗？':'请先在对应平台核对。确认这条消息没有发送，并允许言策重新发送吗？';if(!await window.YanceDialogs.confirm({title:confirmedSent?'确认平台已发送':'确认平台未发送',message:prompt,submitLabel:confirmedSent?'标记为已发送':'重新进入发送队列'}))return;try{const result=await window.YanceCore.messages.resolveOutcome(queueId,resolution),queue=result?.queue||{};sendQueueState={...sendQueueState,...queue,id:queueId,state:String(queue.state||(confirmedSent?'sent':'retry')).toLowerCase(),lastError:queue.lastError||''};renderSendQueueStatus();notify(confirmedSent?'已确认平台已发送，本地记录正在收口':'已确认平台未发送，任务已重新进入发送队列',confirmedSent?'success':'warning')}catch(error){notify(error.message||'发送结果对账失败','error')}}
function renderSendQueueStatus(){const host=$('r32SendQueueStatus');if(!host)return;if(!sendQueueState||['sent','cancelled'].includes(sendQueueState.state)){host.hidden=true;host.innerHTML='';return}const state=String(sendQueueState.state||'queued').toLowerCase(),progress=state==='sending'?72:state==='queued'||state==='pending'?28:state==='retry'?45:state==='platform_accepted_local_pending'?88:state==='send_outcome_unknown'?100:100,queueId=String(sendQueueState.id||sendQueueState.queueId||'');host.dataset.state=state;const reconcileActions=state==='send_outcome_unknown'&&queueId?'<button data-queue-confirm-sent>平台已发送</button><button data-queue-confirm-not-sent>平台未发送，重新发送</button>':'';host.innerHTML=`<div><b>${htmlText(queueStateLabel(state))}</b><span>${htmlText(sendQueueState.lastError||sendQueueState.error?.message||sendQueueState.filename||'媒体和消息会保持在持久化队列中')}</span><progress max="100" value="${htmlAttr(progress)}"></progress></div><div class="r32-send-queue-actions">${reconcileActions}${['retry','failed'].includes(state)&&queueId?'<button data-queue-retry>重试</button>':''}${['queued','pending','sending','retry','failed'].includes(state)&&queueId?'<button data-queue-cancel>取消</button>':''}</div>`;host.hidden=false;host.querySelector('[data-queue-confirm-sent]')?.addEventListener('click',()=>reconcileQueueOutcome(queueId,'confirmed_sent'));host.querySelector('[data-queue-confirm-not-sent]')?.addEventListener('click',()=>reconcileQueueOutcome(queueId,'confirmed_not_sent'));host.querySelector('[data-queue-retry]')?.addEventListener('click',async()=>{try{await window.YanceCore.messages.retry(queueId);sendQueueState={...sendQueueState,state:'queued',lastError:''};renderSendQueueStatus();notify('已重新加入发送队列')}catch(error){notify(error.message||'重试失败','error')}});host.querySelector('[data-queue-cancel]')?.addEventListener('click',async()=>{try{await window.YanceCore.messages.cancel(queueId);sendQueueState={...sendQueueState,state:'cancelled'};renderSendQueueStatus();notify('已取消发送','warning')}catch(error){notify(error.message||'取消失败','error')}})}
function updateSendQueueStatus(event={}){const payload=event.payload||event||{},queue=payload.queue||payload,queueId=String(queue?.id||payload.queueId||'');if(!queueId)return;const current=contact(),sessionKey=String(queue?.sessionKey||payload.sessionKey||'');if(current?.id&&sessionKey&&sessionKey!==String(current.id))return;const eventType=String(event.type||'');let state=String(queue?.state||'').toLowerCase();if(eventType==='send-queue:sent')state='sent';else if(eventType==='send-queue:failed')state='failed';else if(eventType==='send-queue:retry')state='retry';else if(eventType==='send-queue:cancelled')state='cancelled';else if(eventType==='send-queue:enqueued'&&!state)state='queued';sendQueueState={...sendQueueState,...queue,id:queueId,state,lastError:queue?.lastError||payload.error?.message||''};renderSendQueueStatus();if(state==='sent')setTimeout(()=>{if(sendQueueState?.id===queueId){sendQueueState=null;renderSendQueueStatus()}},1800)}
function recentEmoji(){try{return JSON.parse(localStorage.getItem(RECENT_KEY)||'[]').filter(Boolean).slice(0,48)}catch(_){return[]}}
function rememberEmoji(emoji){const next=[emoji,...recentEmoji().filter(x=>x!==emoji)].slice(0,48);localStorage.setItem(RECENT_KEY,JSON.stringify(next))}
function applyTone(emoji){if(!tone||!SKIN_BASE.has(emoji.replace(/[\uFE0F]/g,''))&&!SKIN_BASE.has(emoji))return emoji;return emoji.replace(/[🏻🏼🏽🏾🏿]/gu,'')+tone}
function insertAtCursor(text){const input=$('composerText');if(!input)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+text+input.value.slice(end);input.selectionStart=input.selectionEnd=start+text.length;input.focus();input.dispatchEvent(new Event('input',{bubbles:true}))}
function openDb(){return new Promise((resolve,reject)=>{if(!indexedDB)return reject(new Error('当前环境不支持本地表情收藏'));const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('items')){const store=db.createObjectStore('items',{keyPath:'id'});store.createIndex('kind','kind');store.createIndex('createdAt','createdAt')}};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
