function inferMediaKind(source='',hint=''){
 const explicit=String(hint||'').toLowerCase();if(['image','gif','sticker','video','voice','audio','document','file'].includes(explicit))return explicit;
 const value=String(source||'').split(/[?#]/)[0].toLowerCase();if(/\.(?:mp4|webm|mov|m4v)$/.test(value))return'video';if(/\.(?:ogg|oga|mp3|m4a|wav|webm-audio)$/.test(value))return'audio';if(/\.(?:pdf|docx?|xlsx?|pptx?|zip|rar|7z|txt|csv)$/.test(value))return'document';return'image'
}
function mediaViewerFileName(source='',kind='image'){
 try{const url=new URL(String(source||''),location.href),name=decodeURIComponent(url.pathname.split('/').filter(Boolean).pop()||'');if(name)return name}catch(_){}
 return `Yance-${kind||'media'}`
}
function setMediaViewerScale(value){mediaViewer.scale=Math.max(.25,Math.min(5,Number(value)||1));const image=$('r32MediaViewerImage');if(image)image.style.transform=`scale(${mediaViewer.scale})`;const reset=document.querySelector('[data-media-action="reset"]');if(reset)reset.textContent=`${Math.round(mediaViewer.scale*100)}%`}
function closeMediaViewer(){const overlay=$('r32MediaViewer');if(overlay)overlay.hidden=true;mediaViewer={source:'',scale:1,fileName:'Yance-media',kind:'image'};const stage=overlay?.querySelector('.r32-media-viewer-stage');if(stage)stage.replaceChildren()}
