  const payload=await reconcileIdempotentRequest(()=>fetchJsonWithTimeout('/api/r32/messages/expressions/send',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','Idempotency-Key':idempotencyKey,'X-Yance-Idempotency-Key':idempotencyKey},body:JSON.stringify(body)},{timeoutMs:65000,label:'Telegram 素材发送'}));
  nativeExpressionIdempotencyKeys.delete(identity);
