async function expressionToFile(item){const c=contact();if(item.accountId&&String(item.accountId)!==String(c?.accountId||''))throw new Error('该素材属于另一个登录账号，不能用于当前发送路由');if(item.dataUrl){const blob=await(await fetch(item.dataUrl)).blob();return new File([blob],item.name||`${item.kind}.bin`,{type:item.mimeType||blob.type})}const source=String(item.previewUrl||item.url||'');if(!source||/^https?:/i.test(source))throw new Error(item.supportReason||'素材尚未恢复到本机，请先从历史消息重新同步');const response=await fetch(source);if(!response.ok)throw new Error('本地素材读取失败，请重新同步媒体');const blob=await response.blob();const ext=source.split('.').pop().split('?')[0]||'bin';return new File([blob],item.name||`${item.kind}-${item.sourceMessageId||Date.now()}.${ext}`,{type:item.mimeType||blob.type})}
