async function startRecording(){buildUi();if(!navigator.mediaDevices?.getUserMedia){notify('当前环境不支持麦克风录音','error');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});recordChunks=[];mediaRecorder=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?'audio/webm;codecs=opus':''});mediaRecorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};mediaRecorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(recordTimer);const blob=new Blob(recordChunks,{type:mediaRecorder.mimeType||'audio/webm'});setPending(new File([blob],`voice-${Date.now()}.webm`,{type:blob.type}),'voice');$('r32RecorderOverlay').hidden=true;mediaRecorder=null};recordStarted=Date.now();mediaRecorder.start(250);$('r32RecorderOverlay').hidden=false;recordTimer=setInterval(()=>{const sec=Math.floor((Date.now()-recordStarted)/1000);$('r32RecorderTime').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`},250)}catch(error){notify(`无法使用麦克风：${friendlyErrorMessage(error,'麦克风不可用')}`,'error')}}
function stopRecording(){if(mediaRecorder&&mediaRecorder.state!=='inactive')mediaRecorder.stop()}
