async function runSearch(){const q=($('r32ChatSearchInput').value||'').trim(),host=$('r32ChatSearchResults');if(!q){host.innerHTML='<p>请输入搜索内容</p>';return}host.innerHTML='<p>正在同时搜索原文、中文译文和联系人身份…</p>';try{const payload=await api().apiJson(`/api/r32/messages/search?q=${encodeURIComponent(q)}&limit=100`,{headers:{}}),rows=payload.results||[];host.innerHTML=rows.map(row=>{const original=String(row.text||''),zh=String(row.translatedZh||''),primary=zh||original||'[媒体消息]',showOriginal=Boolean(zh&&original&&zh.trim()!==original.trim()),meta=[row.contactName||'未知联系人',platformName(row.platform),row.sentAt||'',row.messageType||''].filter(Boolean).join(' · ');return `<button class="r32-search-result" data-session="${htmlAttr(row.sessionKey)}" data-message-id="${htmlAttr(row.id||row.externalMessageId||'')}"><strong>${htmlText(primary)}</strong>${showOriginal?`<small class="r32-search-original">原文：${htmlText(original)}</small>`:''}<span>${htmlText(meta)}</span></button>`}).join('')||'<p>没有找到匹配消息</p>';host.querySelectorAll('[data-session]').forEach(b=>b.onclick=async()=>{await api().bootstrapR32?.();await selectBySession(b.dataset.session);$('r32SearchOverlay').hidden=true;focusSearchMessage(b.dataset.messageId)})}catch(error){host.innerHTML=`<p>${htmlText(friendlyErrorMessage(error,'会话搜索失败'))}</p>`}}
