  if(mediaUrl){const response=await fetch(mediaUrl);if(!response.ok)throw new Error(`媒体读取失败（HTTP ${response.status}）`);const blob=await response.blob(),kind=String(message.mediaKind||message.raw?.messageType||message.raw?.type||'image').toLowerCase(),headers={'Content-Type':blob.type||'application/octet-stream','Idempotency-Key':key,'X-Yance-Idempotency-Key':key,'X-Yance-Session-Key':encodeURIComponent(target.id||''),'X-Yance-Chat-Jid':encodeURIComponent(target.chatJid),'X-Yance-Media-Kind':encodeURIComponent(kind),'X-Yance-Mime-Type':encodeURIComponent(blob.type||'application/octet-stream'),'X-Yance-Filename':encodeURIComponent(mediaFileName(mediaUrl)),'X-Yance-Caption':encodeURIComponent(messageOriginalText(message))};payload=await reconcileIdempotentRequest(()=>fetchJsonWithTimeout(`/api/r32/messages/${encodeURIComponent(platform)}/${encodeURIComponent(target.accountId)}/send-media-stream`,{method:'POST',headers,body:blob},{timeoutMs:90000,label:'媒体转发'}))}
