const BIND_REQUIRED_IDS=['emojiBtn','gifBtn','imageBtn','voiceBtn','chatSearch','moreBtn','imageInput','sendBtn','composerText','messages'];
let capabilityBindingsReady=false,capabilityBindAttempts=0,capabilityBindTimer=0,capabilityBindObserver=null,capabilityBindError='',capabilityWindowEventsBound=false,capabilityDesktopEventsBound=false;
function bindingSnapshot(status='pending',missing=[]){
 const snapshot={status,ready:capabilityBindingsReady,attempts:capabilityBindAttempts,missing:[...missing],error:capabilityBindError,updatedAt:new Date().toISOString()};
 window.__YanceConversationCapabilitiesStatus=snapshot;
 return snapshot;
}
function scheduleCapabilityBind(){
 if(capabilityBindingsReady||capabilityBindTimer)return;
 const delay=Math.min(2000,50*Math.max(1,capabilityBindAttempts));
 capabilityBindTimer=window.setTimeout(()=>{capabilityBindTimer=0;bind()},delay);
}
function bind(){
 if(capabilityBindingsReady)return true;
 capabilityBindAttempts+=1;
 try{
  buildUi();
  const missing=BIND_REQUIRED_IDS.filter(id=>!$(id));
  if(missing.length){capabilityBindError='';bindingSnapshot('waiting-for-dom',missing);scheduleCapabilityBind();return false}
  bindNow();
  capabilityBindingsReady=true;
  capabilityBindError='';
  bindingSnapshot('ready',[]);
  capabilityBindObserver?.disconnect?.();
  capabilityBindObserver=null;
  if(capabilityBindTimer){clearTimeout(capabilityBindTimer);capabilityBindTimer=0}
  window.dispatchEvent(new CustomEvent('yance:r32-conversation-capabilities-ready',{detail:window.__YanceConversationCapabilitiesStatus}));
  return true;
 }catch(error){
  capabilityBindError=String(error?.message||error||'conversation capability binding failed');
  const missing=BIND_REQUIRED_IDS.filter(id=>!$(id));
  bindingSnapshot('binding-error',missing);
  console.error('[R32 conversation capabilities binding]',error);
  scheduleCapabilityBind();
  return false;
 }
}
function observeCapabilityDom(){
 if(capabilityBindingsReady||capabilityBindObserver||typeof MutationObserver!=='function')return;
 capabilityBindObserver=new MutationObserver(()=>{if(!capabilityBindingsReady)bind()});
 const root=document.documentElement||document.body;
 if(root)capabilityBindObserver.observe(root,{childList:true,subtree:true});
}
window.YanceR32ConversationCapabilities={bind,status:()=>({...window.__YanceConversationCapabilitiesStatus,missing:[...(window.__YanceConversationCapabilitiesStatus?.missing||[])]}),showExpression,setPending,clearPending,hasPendingAttachment:()=>Boolean(pending),currentQuote,clearQuote,sendPendingAttachment,startRecording,openMediaViewer,openCapabilityDialog,updateSendQueueStatus,loadPersistedSendQueueState,schedulePersistedSendQueueState};
